<?php if (!isset($detailResource,$files)) { http_response_code(404);exit; } ?>
<section class="rd-preview-panel" id="resource-list"><h2><span class="rd-search-icon" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="13" cy="13" r="8"/><path d="m19 19 8 8"/></svg></span>Preview the <?php echo $detailResource['category']==='templates'?'template':'resource'; ?></h2>
